values
  ('t1-r1-31', 't1-r1', 31, 'topic', null, '저는 한국 사람입니다. 친구는 일본 사람입니다.', null, '["나이","직업","이름","나라"]'::jsonb, 4, '한국 사람 / 일본 사람 → countries.'),
  ('t1-r1-32', 't1-r1', 32, 'topic', null, '오늘은 월요일입니다. 내일은 화요일입니다.', null, '["날씨","나이","장소","요일"]'::jsonb, 4, '월요일, 화요일 are days of the week.'),
  ('t1-r1-33', 't1-r1', 33, 'topic', null, '저는 사과를 좋아합니다. 동생은 포도를 좋아합니다.', null, '["가족","과일","운동","계절"]'::jsonb, 2, '사과 (apple), 포도 (grapes) → fruit.'),
  ('t1-r1-34', 't1-r1', 34, 'blank', null, '목이 마릅니다. (    )을 마십니다.', null, '["밥","옷","물","책"]'::jsonb, 3, 'Thirsty → drink water. 밥 is eaten, not drunk.'),
  ('t1-r1-35', 't1-r1', 35, 'blank', null, '학교(    ) 공부합니다.', null, '["를","에서","이","의"]'::jsonb, 2, '에서 marks the place where an action happens.'),
  ('t1-r1-36', 't1-r1', 36, 'blank', null, '친구(    ) 전화를 했습니다.', null, '["의","에서","를","에게"]'::jsonb, 4, '에게 = to (a person): I called my friend.'),
  ('t1-r1-37', 't1-r1', 37, 'blank', null, '배가 아픕니다. 그래서 (    )에 갑니다.', null, '["극장","서점","병원","은행"]'::jsonb, 3, 'A stomachache → go to the hospital.'),
  ('t1-r1-38', 't1-r1', 38, 'blank', null, '방이 (    ). 그래서 청소를 합니다.', null, '["따뜻합니다","조용합니다","넓습니다","더럽습니다"]'::jsonb, 4, 'The room is dirty, so I clean it.'),
  ('t1-r1-39', 't1-r1', 39, 'blank', null, '저는 노래를 잘 못 합니다. 그렇지만 노래를 (    ).', null, '["싫어합니다","모릅니다","못 합니다","좋아합니다"]'::jsonb, 4, '그렇지만 (but) needs a contrast: not good at it, but I like it.'),
  ('t1-r1-40', 't1-r1', 40, 'notice', null, '[한국 요리 교실]
